package com.example.finance.presentation;

import android.Manifest;
import android.app.*;
import android.content.pm.PackageManager;
import android.graphics.Color;
import android.os.*;
import android.view.*;
import android.widget.*;
import androidx.activity.ComponentActivity;
import androidx.lifecycle.ViewModelProvider;
import androidx.core.content.ContextCompat;
import androidx.work.*;
import com.example.finance.data.*;
import com.example.finance.data.Operation;
import com.example.finance.domain.BudgetCalculator;
import com.example.finance.domain.CardExpiry;
import com.example.finance.notification.ReminderWorker;
import java.text.NumberFormat;
import java.util.*;
import java.util.concurrent.TimeUnit;

public class MainActivity extends ComponentActivity {
 private FinanceViewModel vm; private LinearLayout body; private List<Account> accounts=new ArrayList<>(); private List<CategoryDetails> categories=new ArrayList<>();
 @Override public void onCreate(Bundle state){super.onCreate(state); vm=new ViewModelProvider(this).get(FinanceViewModel.class); showHome(); vm.accounts.observe(this,a->{accounts=a; render();}); vm.categories.observe(this,c->{categories=c;render();showLegacyNotice(c);}); if(Build.VERSION.SDK_INT>=33 && ContextCompat.checkSelfPermission(this,Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED) requestPermissions(new String[]{Manifest.permission.POST_NOTIFICATIONS},1);}
 private void showLegacyNotice(List<CategoryDetails> data){if(getPreferences(MODE_PRIVATE).getBoolean("legacy_balance_notice",false))return;boolean legacy=false;for(CategoryDetails c:data)for(Operation o:c.operations)if(!o.appliedToBalance){legacy=true;break;}if(!legacy)return;getPreferences(MODE_PRIVATE).edit().putBoolean("legacy_balance_notice",true).apply();new AlertDialog.Builder(this).setTitle("Укажите остатки счетов").setMessage("Раньше приложение не хранило остатки. Сохранённые расходы остались в истории, но не учитываются в остатке. В каждом счёте выберите «Пополнить счёт» и укажите его текущий фактический остаток.").setPositiveButton("Понятно",null).show();}
 private TextView text(String s,int size){TextView v=FinanceStyle.label(this,s,size,FinanceStyle.INK,size>=18);v.setPadding(0,FinanceStyle.dp(this,6),0,FinanceStyle.dp(this,6));return v;}
 private void showHome(){
  getWindow().setStatusBarColor(FinanceStyle.BACKGROUND);getWindow().setNavigationBarColor(FinanceStyle.BACKGROUND);
  getWindow().getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR);
  ScrollView scroll=new ScrollView(this);scroll.setFillViewport(true);scroll.setBackgroundColor(FinanceStyle.BACKGROUND);setContentView(scroll);
  LinearLayout root=new LinearLayout(this);root.setOrientation(1);int pad=FinanceStyle.dp(this,20);root.setPadding(pad,pad,pad,FinanceStyle.dp(this,28));scroll.addView(root);
  TextView heading=FinanceStyle.label(this,"Личные финансы",27,FinanceStyle.INK,true);root.addView(heading);
  java.text.SimpleDateFormat fmt=new java.text.SimpleDateFormat("LLLL yyyy",new Locale("ru","RU"));TextView subtitle=FinanceStyle.label(this,fmt.format(new Date()),14,FinanceStyle.MUTED,false);root.addView(subtitle);FinanceStyle.addSpace(root,20);
  body=new LinearLayout(this);body.setOrientation(1);root.addView(body);render();
 }
 private void button(LinearLayout parent,String title,Runnable action){TextView b=FinanceStyle.action(this,title,false,action);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.bottomMargin=FinanceStyle.dp(this,8);parent.addView(b,lp);}
 private void actionRow(LinearLayout parent,String left,Runnable l,String right,Runnable r){LinearLayout row=new LinearLayout(this);row.setOrientation(0);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,-2,1);lp.rightMargin=FinanceStyle.dp(this,8);row.addView(FinanceStyle.action(this,left,false,l),lp);row.addView(FinanceStyle.action(this,right,false,r),new LinearLayout.LayoutParams(0,-2,1));FinanceStyle.addCard(parent,row);}
 private void render(){
  if(body==null)return;body.removeAllViews();Calendar cal=Calendar.getInstance();cal.set(Calendar.DAY_OF_MONTH,1);cal.set(Calendar.HOUR_OF_DAY,0);cal.set(Calendar.MINUTE,0);cal.set(Calendar.SECOND,0);cal.set(Calendar.MILLISECOND,0);long month=cal.getTimeInMillis();long total=0;
  for(CategoryDetails d:categories)for(Operation o:d.operations)if(o.createdAt>=month&&o.createdAt<=System.currentTimeMillis())total+=o.amount;
  LinearLayout summary=FinanceStyle.column(this,FinanceStyle.PALE_BLUE,20);summary.addView(FinanceStyle.label(this,"Расходы за месяц",14,0xFF365B69,false));FinanceStyle.addSpace(summary,8);summary.addView(FinanceStyle.label(this,money(total),30,0xFF001F2B,true));FinanceStyle.addSpace(summary,8);summary.addView(FinanceStyle.label(this,"Локальный учёт · не подключён к банку",14,0xFF365B69,false));FinanceStyle.addCard(body,summary);
  FinanceStyle.addSpace(body,6);FinanceStyle.addCard(body,FinanceStyle.action(this,"+  Добавить расход",true,this::addExpense));actionRow(body,"+ Счёт",()->nameDialog(true),"+ Категория",()->nameDialog(false));
  FinanceStyle.addCard(body,FinanceStyle.action(this,"◷  Напоминания",false,this::reminderMenu));FinanceStyle.addSpace(body,12);
  body.addView(text("Мои счета и карты",20));FinanceStyle.addSpace(body,4);
  if(accounts.isEmpty()){LinearLayout empty=FinanceStyle.column(this,FinanceStyle.WHITE,18);empty.addView(FinanceStyle.label(this,"Пока нет счетов",16,FinanceStyle.INK,true));FinanceStyle.addSpace(empty,5);empty.addView(FinanceStyle.label(this,"Добавьте счёт, чтобы записывать расходы.",14,FinanceStyle.MUTED,false));FinanceStyle.addCard(body,empty);}
  for(Account a:accounts){LinearLayout card=FinanceStyle.column(this,0xFFE4EEF1,18);card.addView(FinanceStyle.label(this,a.closed?"▣   ЗАКРЫТЫЙ СЧЁТ":"▣   СЧЁТ",12,FinanceStyle.PRIMARY,true));FinanceStyle.addSpace(card,10);card.addView(FinanceStyle.label(this,a.name,18,FinanceStyle.INK,true));FinanceStyle.addSpace(card,4);card.addView(FinanceStyle.label(this,"Остаток  ·  "+money(a.balance),16,FinanceStyle.INK,true));String expiry=expiryStatus(a);if(!expiry.isEmpty()){FinanceStyle.addSpace(card,4);card.addView(FinanceStyle.label(this,expiry,13,0xFF9A5800,true));}FinanceStyle.addSpace(card,4);card.addView(FinanceStyle.label(this,"Нажмите для управления  ›",13,FinanceStyle.MUTED,false));card.setOnClickListener(v->accountActions(a));FinanceStyle.addCard(body,card);}
  FinanceStyle.addSpace(body,12);body.addView(text("Категории и лимиты",20));FinanceStyle.addSpace(body,4);
  if(categories.isEmpty()){LinearLayout empty=FinanceStyle.column(this,FinanceStyle.WHITE,18);empty.addView(FinanceStyle.label(this,"Начните с категории",16,FinanceStyle.INK,true));FinanceStyle.addSpace(empty,5);empty.addView(FinanceStyle.label(this,"Добавьте категорию и установите месячный лимит.",14,FinanceStyle.MUTED,false));FinanceStyle.addCard(body,empty);}
  for(CategoryDetails d:categories){long spent=0;for(Operation o:d.operations)if(o.createdAt>=month&&o.createdAt<=System.currentTimeMillis())spent+=o.amount;Budget b=d.budgets.isEmpty()?null:d.budgets.get(0);BudgetCalculator.Level level=BudgetCalculator.level(spent,b==null?0:b.amount,b==null?80:b.warningPercent);
   int accent=level==BudgetCalculator.Level.EXCEEDED?0xFFB3261E:level==BudgetCalculator.Level.WARNING?0xFF9A5800:0xFF1B8754;String status=level==BudgetCalculator.Level.EXCEEDED?"●  Лимит превышен":level==BudgetCalculator.Level.WARNING?"▲  Приближение к лимиту":level==BudgetCalculator.Level.NONE?"○  Лимит не задан":"✓  В пределах лимита";
   LinearLayout card=FinanceStyle.column(this,FinanceStyle.WHITE,18);card.addView(FinanceStyle.label(this,d.category.name,18,FinanceStyle.INK,true));FinanceStyle.addSpace(card,8);card.addView(FinanceStyle.label(this,"Расход за месяц  ·  "+money(spent),15,FinanceStyle.MUTED,false));if(b!=null){FinanceStyle.addSpace(card,4);card.addView(FinanceStyle.label(this,"Остаток  ·  "+money(b.amount-spent),15,FinanceStyle.INK,true));}FinanceStyle.addSpace(card,10);card.addView(FinanceStyle.label(this,status,14,accent,true));FinanceStyle.addSpace(card,4);card.addView(FinanceStyle.label(this,"Подробнее  ›",13,FinanceStyle.PRIMARY,false));card.setOnClickListener(v->categoryDetails(d));FinanceStyle.addCard(body,card);
  }
 }
 private String money(long cents){return NumberFormat.getCurrencyInstance(new Locale("ru","RU")).format(cents/100.0);}
 private EditText input(String hint){EditText e=new EditText(this);e.setHint(hint);e.setSingleLine(true);e.setTextSize(16);e.setTextColor(FinanceStyle.INK);e.setHintTextColor(FinanceStyle.MUTED);e.setBackground(FinanceStyle.shape(0xFFF1F5F6,12,this));int p=FinanceStyle.dp(this,14);e.setPadding(p,p,p,p);e.setMinHeight(FinanceStyle.dp(this,52));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.bottomMargin=FinanceStyle.dp(this,12);e.setLayoutParams(lp);return e;}
 private LinearLayout form(){LinearLayout box=new LinearLayout(this);box.setOrientation(1);int p=FinanceStyle.dp(this,20);box.setPadding(p,FinanceStyle.dp(this,8),p,FinanceStyle.dp(this,8));return box;}
 private void executeDialog(AlertDialog dialog,Runnable task,java.util.function.Consumer<String> result){android.widget.Button button=dialog.getButton(AlertDialog.BUTTON_POSITIVE);button.setEnabled(false);vm.repository.execute(task,err->{button.setEnabled(true);result.accept(err);});}
 private void saveDialog(AlertDialog dialog,Runnable save){dialog.setOnShowListener(x->dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->save.run()));dialog.show();}
 private void nameDialog(boolean account){LinearLayout box=form();TextView label=FinanceStyle.label(this,"Название",14,FinanceStyle.INK,true);box.addView(label);FinanceStyle.addSpace(box,6);EditText e=input(account?"Например, Основная карта":"Например, Продукты");e.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(60)});box.addView(e);MonthYearField expiry=new MonthYearField(this,"");if(account)box.addView(expiry);AlertDialog dialog=new AlertDialog.Builder(this).setTitle(account?"Новый счёт":"Новая категория").setView(box).setNegativeButton("Отмена",null).setPositiveButton("Сохранить",null).create();saveDialog(dialog,()->{String n=e.getText().toString().trim(),ex=expiry.getValue();if(n.isEmpty()){e.setError("Введите название");return;}executeDialog(dialog,()->{if(account){Account a=new Account();a.name=n;a.expiry=ex;vm.repository.dao.createAccount(a);}else{Category c=new Category();c.name=n;vm.repository.dao.addCategory(c);}},err->{if(err!=null)toast(err);else dialog.dismiss();});});}
 private String expiryStatus(Account a){if(a.closed||a.expiry.isEmpty())return "";Calendar c=Calendar.getInstance();int now=c.get(Calendar.YEAR)*12+c.get(Calendar.MONTH);int exp=Integer.parseInt(a.expiry.substring(0,4))*12+Integer.parseInt(a.expiry.substring(5))-1;int remaining=exp-now;if(remaining<0)return "▲ Срок карты истёк · "+a.expiry;if(remaining<=2)return "▲ Срок карты заканчивается · "+a.expiry;return "Срок карты · "+a.expiry;}
 private List<Account> activeAccounts(long except){List<Account> list=new ArrayList<>();for(Account a:accounts)if(!a.closed&&a.id!=except)list.add(a);return list;}
 private void accountActions(Account a){if(a.closed){new AlertDialog.Builder(this).setTitle(a.name).setMessage("Счёт закрыт. Его операции сохранены в истории категорий.").setPositiveButton("История переводов",(d,w)->showMovements(a)).setNegativeButton("Закрыть",null).show();return;}new AlertDialog.Builder(this).setTitle(a.name+" · "+money(a.balance)).setItems(new String[]{"Пополнить счёт","Перевести на другой счёт","Изменить название и срок","История переводов","Закрыть счёт"},(d,i)->{if(i==0)depositDialog(a);else if(i==1)transferDialog(a,false);else if(i==2)editAccount(a);else if(i==3)showMovements(a);else closeAccount(a);}).show();}
 private void editAccount(Account a){LinearLayout box=form();box.addView(FinanceStyle.label(this,"Название",14,FinanceStyle.INK,true));FinanceStyle.addSpace(box,6);EditText name=input("Название счёта");name.setText(a.name);name.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(60)});box.addView(name);MonthYearField expiry=new MonthYearField(this,a.expiry);box.addView(expiry);AlertDialog dialog=new AlertDialog.Builder(this).setTitle("Изменить счёт").setView(box).setNegativeButton("Отмена",null).setPositiveButton("Сохранить",null).create();saveDialog(dialog,()->{String n=name.getText().toString().trim(),ex=expiry.getValue();if(n.isEmpty()){name.setError("Введите название");return;}executeDialog(dialog,()->vm.repository.dao.editAccount(a.id,n,ex),err->{if(err==null)dialog.dismiss();else toast(err);});});}
 private void depositDialog(Account a){EditText e=input("Сумма в рублях");e.setInputType(8194);AlertDialog dialog=new AlertDialog.Builder(this).setTitle("Пополнить · "+a.name).setMessage("Укажите поступившую сумму. Это запись в приложении, а не банковская операция.").setView(e).setNegativeButton("Отмена",null).setPositiveButton("Сохранить",null).create();saveDialog(dialog,()->{Long n=amount(e);if(n==null)return;executeDialog(dialog,()->vm.repository.dao.deposit(a.id,n),err->{if(err==null)dialog.dismiss();else toast(err);});});}
 private void closeAccount(Account a){if(a.balance==0){new AlertDialog.Builder(this).setTitle("Закрыть счёт?").setMessage("Счёт будет закрыт, а история операций сохранится.").setNegativeButton("Отмена",null).setPositiveButton("Закрыть счёт",(d,w)->vm.repository.execute(()->vm.repository.dao.closeEmpty(a.id),err->{if(err!=null)toast(err);else toast("Счёт закрыт");})).show();}else transferDialog(a,true);}
 private void transferDialog(Account a,boolean close){List<Account> targets=activeAccounts(a.id);if(targets.isEmpty()){new AlertDialog.Builder(this).setTitle(close?"Нельзя закрыть счёт":"Нет другого счёта").setMessage(close?"На счёте есть "+money(a.balance)+". Добавьте другой счёт и переведите на него остаток перед закрытием.":"Добавьте ещё один счёт для перевода.").setPositiveButton("Понятно",null).show();return;}LinearLayout box=form();TextView hint=text(close?"Чтобы закрыть счёт, переведите весь остаток: "+money(a.balance):"Доступно: "+money(a.balance),15);box.addView(hint);Spinner target=new Spinner(this);List<String> names=new ArrayList<>();for(Account b:targets)names.add(b.name+" · "+money(b.balance));target.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,names));box.addView(target);EditText sum=input("Сумма в рублях");sum.setInputType(8194);if(!close)box.addView(sum);AlertDialog dialog=new AlertDialog.Builder(this).setTitle(close?"Перевод и закрытие":"Перевод между счетами").setView(box).setNegativeButton("Отмена",null).setPositiveButton(close?"Перевести и закрыть":"Перевести",null).create();saveDialog(dialog,()->{Long n=close?a.balance:amount(sum);if(n==null)return;long id=targets.get(target.getSelectedItemPosition()).id;executeDialog(dialog,()->vm.repository.dao.transfer(a.id,id,n,close),err->{if(err==null){dialog.dismiss();toast(close?"Остаток переведён, счёт закрыт":"Перевод сохранён");}else toast(err);});});}
 private void showMovements(Account a){vm.repository.run(()->{List<AccountMovement> items=vm.repository.dao.movements(a.id);StringBuilder s=new StringBuilder();java.text.DateFormat date=java.text.DateFormat.getDateTimeInstance();for(AccountMovement m:items){String direction=m.sourceId!=null&&m.sourceId==a.id?"−":"+";s.append(m.type).append("  ").append(direction).append(money(m.amount)).append("\n").append(date.format(new Date(m.createdAt))).append("\n\n");}runOnUiThread(()->new AlertDialog.Builder(this).setTitle("История · "+a.name).setMessage(items.isEmpty()?"Переводов и пополнений пока нет.":s.toString()).setPositiveButton("Закрыть",null).show());});}
 private void categoryDetails(CategoryDetails d){final AlertDialog[] parent={null};LinearLayout box=form();button(box,"Месячный лимит",()->{parent[0].dismiss();limitDialog(d);});button(box,"Переименовать категорию",()->{parent[0].dismiss();renameCategory(d.category);});button(box,"Удалить категорию",()->{parent[0].dismiss();confirm("Удалить категорию и её лимит? Категория с операциями не может быть удалена.",()->vm.repository.execute(()->vm.repository.dao.removeCategory(d.category),err->{if(err!=null)toast(err);}));});FinanceStyle.addSpace(box,12);box.addView(text("История расходов",18));if(d.operations.isEmpty())box.addView(text("Пока нет операций в этой категории.",14));java.text.DateFormat date=java.text.DateFormat.getDateInstance();for(Operation o:d.operations){LinearLayout card=FinanceStyle.column(this,0xFFF1F5F6,14);card.addView(FinanceStyle.label(this,o.note.isEmpty()?"Расход":o.note,16,FinanceStyle.INK,true));FinanceStyle.addSpace(card,4);card.addView(FinanceStyle.label(this,money(o.amount)+" · "+date.format(new Date(o.createdAt)),14,FinanceStyle.MUTED,false));FinanceStyle.addSpace(card,4);card.addView(FinanceStyle.label(this,"Управление  ›",13,FinanceStyle.PRIMARY,true));card.setOnClickListener(v->{parent[0].dismiss();expenseActions(o);});FinanceStyle.addCard(box,card);}ScrollView scroll=new ScrollView(this);scroll.addView(box);parent[0]=new AlertDialog.Builder(this).setTitle(d.category.name).setView(scroll).setPositiveButton("Закрыть",null).create();parent[0].show();}
 private void expenseActions(Operation o){new AlertDialog.Builder(this).setTitle(o.note.isEmpty()?"Расход":o.note).setMessage("Сумма: "+money(o.amount)).setNegativeButton("Отмена",null).setNeutralButton("Удалить",(d,w)->confirm(o.appliedToBalance?"Удалить расход и вернуть сумму на счёт?":"Удалить прежнюю операцию? Остаток счёта не изменится.",()->vm.repository.execute(()->vm.repository.dao.removeExpense(o.id),err->{if(err!=null)toast(err);else toast("Расход удалён");}))).setPositiveButton("Изменить",(d,w)->editExpense(o)).show();}
 private void editExpense(Operation o){if(!o.appliedToBalance){toast("Старую операцию без учёта остатка нельзя редактировать");return;}LinearLayout box=form();box.addView(FinanceStyle.label(this,"Сумма, ₽",14,FinanceStyle.INK,true));FinanceStyle.addSpace(box,6);EditText sum=input("Сумма"),note=input("Описание (необязательно)");sum.setInputType(8194);sum.setText(java.math.BigDecimal.valueOf(o.amount,2).toPlainString());note.setText(o.note);box.addView(sum);box.addView(FinanceStyle.label(this,"Описание",14,FinanceStyle.INK,true));FinanceStyle.addSpace(box,6);box.addView(note);AlertDialog dialog=new AlertDialog.Builder(this).setTitle("Изменить расход").setView(box).setNegativeButton("Отмена",null).setPositiveButton("Сохранить",null).create();saveDialog(dialog,()->{Long amount=amount(sum);if(amount==null)return;String description=note.getText().toString().trim();executeDialog(dialog,()->vm.repository.dao.editExpense(o.id,amount,description),err->{if(err==null){dialog.dismiss();toast("Расход изменён");}else toast(err);});});}
 private void renameCategory(Category c){LinearLayout box=form();box.addView(FinanceStyle.label(this,"Название",14,FinanceStyle.INK,true));FinanceStyle.addSpace(box,6);EditText e=input("Название категории");e.setText(c.name);e.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(60)});box.addView(e);AlertDialog dialog=new AlertDialog.Builder(this).setTitle("Категория").setView(box).setPositiveButton("Сохранить",null).setNegativeButton("Отмена",null).create();saveDialog(dialog,()->{String name=e.getText().toString().trim();if(name.isEmpty()){e.setError("Введите название");return;}executeDialog(dialog,()->{c.name=name;vm.repository.dao.updateCategory(c);},err->{if(err==null)dialog.dismiss();else toast(err);});});}
 private Long amount(EditText e){try{long n=new java.math.BigDecimal(e.getText().toString().replace(',','.')).movePointRight(2).longValueExact();if(n<=0)throw new Exception();return n;}catch(Exception ex){e.setError("Введите положительную сумму с точностью до копеек");return null;}}
 private void limitDialog(CategoryDetails d){EditText e=input("Лимит в рублях");e.setInputType(8194);AlertDialog dialog=new AlertDialog.Builder(this).setTitle("Месячный лимит · "+d.category.name).setView(e).setNegativeButton("Отмена",null).setPositiveButton("Сохранить",null).create();saveDialog(dialog,()->{Long n=amount(e);if(n==null)return;Budget b=d.budgets.isEmpty()?new Budget():d.budgets.get(0);b.categoryId=d.category.id;b.amount=n;executeDialog(dialog,()->vm.repository.dao.putBudget(b),err->{if(err==null)dialog.dismiss();else toast(err);});});}
 private void addExpense(){List<Account> aa=activeAccounts(-1);if(aa.isEmpty()||categories.isEmpty()){new AlertDialog.Builder(this).setTitle("Добавление расхода").setMessage("Сначала добавьте активный счёт и категорию. Для записи расхода на счёте должны быть средства.").setPositiveButton("Понятно",null).show();return;}LinearLayout box=form();Spinner as=new Spinner(this),cs=new Spinner(this);List<CategoryDetails> cc=new ArrayList<>(categories);List<String> an=new ArrayList<>(),cn=new ArrayList<>();for(Account a:aa)an.add(a.name+" · "+money(a.balance));for(CategoryDetails c:cc)cn.add(c.category.name);as.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,an));cs.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,cn));EditText sum=input("Сумма в рублях"),note=input("Описание (необязательно)");sum.setInputType(8194);box.addView(text("Счёт",14));box.addView(as);box.addView(text("Категория",14));box.addView(cs);box.addView(sum);box.addView(note);AlertDialog dialog=new AlertDialog.Builder(this).setTitle("Новый расход").setView(box).setNegativeButton("Отмена",null).setPositiveButton("Сохранить",null).create();saveDialog(dialog,()->{Long n=amount(sum);if(n==null)return;Operation o=new Operation();o.accountId=aa.get(as.getSelectedItemPosition()).id;CategoryDetails c=cc.get(cs.getSelectedItemPosition());o.categoryId=c.category.id;o.amount=n;o.note=note.getText().toString().trim();o.createdAt=System.currentTimeMillis();executeDialog(dialog,()->vm.repository.dao.spend(o),err->{if(err!=null){toast(err);return;}dialog.dismiss();if(!c.budgets.isEmpty()){Calendar cal=Calendar.getInstance();cal.set(Calendar.DAY_OF_MONTH,1);cal.set(Calendar.HOUR_OF_DAY,0);cal.set(Calendar.MINUTE,0);cal.set(Calendar.SECOND,0);cal.set(Calendar.MILLISECOND,0);long total=n;for(Operation old:c.operations)if(old.createdAt>=cal.getTimeInMillis())total+=old.amount;Budget b=c.budgets.get(0);BudgetCalculator.Level l=BudgetCalculator.level(total,b.amount,b.warningPercent);if(getPreferences(MODE_PRIVATE).getBoolean("limit_warnings",true)&&(l==BudgetCalculator.Level.WARNING||l==BudgetCalculator.Level.EXCEEDED))schedule("limit-"+c.category.id,"Лимит: "+c.category.name,l==BudgetCalculator.Level.EXCEEDED?"Лимит превышен":"Расходы приближаются к лимиту",0,false);}});});}
 private void reminderMenu(){boolean warnings=getPreferences(MODE_PRIVATE).getBoolean("limit_warnings",true);new AlertDialog.Builder(this).setTitle("Напоминания").setItems(new String[]{"Добавить напоминание о платеже",warnings?"Выключить предупреждения о лимитах":"Включить предупреждения о лимитах","Отменить напоминания о платежах"},(d,i)->{if(i==0)reminderDialog();else if(i==1){getPreferences(MODE_PRIVATE).edit().putBoolean("limit_warnings",!warnings).apply();if(warnings)WorkManager.getInstance(this).cancelAllWorkByTag("budget-alert");toast(warnings?"Предупреждения выключены":"Предупреждения включены");}else new AlertDialog.Builder(this).setTitle("Отменить напоминания?").setMessage("Все запланированные в этой версии напоминания о платежах будут отменены.").setNegativeButton("Назад",null).setPositiveButton("Отменить напоминания",(x,y)->{WorkManager.getInstance(this).cancelAllWorkByTag("payment-reminder");toast("Напоминания отменены");}).show();}).show();}
 private void reminderDialog(){LinearLayout box=form();box.addView(FinanceStyle.label(this,"Название платежа",14,FinanceStyle.INK,true));FinanceStyle.addSpace(box,6);EditText name=input("Например, Интернет");box.addView(name);Calendar selected=Calendar.getInstance();selected.add(Calendar.HOUR_OF_DAY,1);TextView when=FinanceStyle.action(this,"",false,()->{});Runnable update=()->when.setText(android.text.format.DateFormat.format("dd.MM.yyyy · HH:mm",selected));update.run();when.setOnClickListener(v->{Calendar base=Calendar.getInstance();DatePickerDialog date=new DatePickerDialog(this,(view,year,month,day)->{selected.set(Calendar.YEAR,year);selected.set(Calendar.MONTH,month);selected.set(Calendar.DAY_OF_MONTH,day);new TimePickerDialog(this,(picker,hour,minute)->{selected.set(Calendar.HOUR_OF_DAY,hour);selected.set(Calendar.MINUTE,minute);selected.set(Calendar.SECOND,0);selected.set(Calendar.MILLISECOND,0);update.run();},selected.get(Calendar.HOUR_OF_DAY),selected.get(Calendar.MINUTE),true).show();},selected.get(Calendar.YEAR),selected.get(Calendar.MONTH),selected.get(Calendar.DAY_OF_MONTH));date.getDatePicker().setMinDate(base.getTimeInMillis()-1000);date.show();});box.addView(FinanceStyle.label(this,"Дата и время",14,FinanceStyle.INK,true));FinanceStyle.addSpace(box,6);box.addView(when);FinanceStyle.addSpace(box,10);CheckBox monthly=new CheckBox(this);monthly.setText("Повторять каждые 30 дней");box.addView(monthly);AlertDialog dialog=new AlertDialog.Builder(this).setTitle("Напоминание о платеже").setView(box).setNegativeButton("Отмена",null).setPositiveButton("Запланировать",null).create();saveDialog(dialog,()->{String title=name.getText().toString().trim();if(title.isEmpty()){name.setError("Введите название платежа");return;}long delay=selected.getTimeInMillis()-System.currentTimeMillis();if(delay<=0){toast("Выберите будущее время");return;}if(Build.VERSION.SDK_INT>=33&&ContextCompat.checkSelfPermission(this,Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{Manifest.permission.POST_NOTIFICATIONS},1);toast("Без разрешения уведомление не появится; напоминание сохранено");}schedule("payment-"+UUID.randomUUID(),"Регулярный платёж",title,Math.max(1,(delay+59999)/60000),monthly.isChecked());dialog.dismiss();toast("Напоминание запланировано");});}
 private void schedule(String key,String title,String content,long delay,boolean repeat){Data data=new Data.Builder().putInt("id",key.hashCode()).putString("title",title).putString("text",content).build();WorkManager wm=WorkManager.getInstance(this);if(repeat){PeriodicWorkRequest r=new PeriodicWorkRequest.Builder(ReminderWorker.class,30,TimeUnit.DAYS).setInitialDelay(delay,TimeUnit.MINUTES).setInputData(data).addTag("payment-reminder").build();wm.enqueueUniquePeriodicWork(key,ExistingPeriodicWorkPolicy.UPDATE,r);}else{OneTimeWorkRequest r=new OneTimeWorkRequest.Builder(ReminderWorker.class).setInitialDelay(delay,TimeUnit.MINUTES).setInputData(data).addTag(key.startsWith("payment-")?"payment-reminder":"budget-alert").build();wm.enqueueUniqueWork(key,ExistingWorkPolicy.REPLACE,r);}}
 private void confirm(String msg,Runnable action){new AlertDialog.Builder(this).setMessage(msg).setNegativeButton("Отмена",null).setPositiveButton("Удалить",(d,w)->action.run()).show();}private void toast(String msg){Toast.makeText(this,msg,Toast.LENGTH_LONG).show();}
}
